scwin.upd_attachMovie = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachMovie') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachMovie"]');

scwin.upd_attachMovie2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachMovie2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachMovie2"]');

scwin.attachFile_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFile_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFile_2"]');

scwin.attachFile_2_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFile_2_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFile_2_3"]');

scwin.upd_attachMovie3 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachMovie3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachMovie3"]');

scwin.attachFile_3_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFile_3_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFile_3_2"]');

scwin.chkFile = chkFile;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
        scwin.init_sessionFill();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05506.onpageload' });
    }
};


