    /* sdd-asis-lifecycle:begin fn_checkboxChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    obj.checked = true;
    scwin.attachSizeReset(obj, obj.name.replace('Chk', '') + "Size", '');
    /* sdd-asis-lifecycle:end */
};
